def rx_gate(value=None):
    """ Return a 1-qubit QuantumCircuit with a parametrized Rx gate and parameter "theta". If value is not None, return the circuit with value assigned to theta. """
    theta = Parameter('theta')
    circuit = QuantumCircuit(1)
    circuit.rx(theta, 0)
    if value is not None:
        try:
            # Convert the value to a numeric type
            numeric_value = float(value)
            circuit.assign_parameters({theta: numeric_value})
        except ValueError:
            raise ValueError("The provided value is not a valid number.")
    return circuit
